<?php
declare(strict_types=1);
require __DIR__.'/company-gamification.php';
use App\Services\{DoctorReactivationService,CareService,IndustryService,Crypto};
$program=new IndustryService($s,$manager);$config=$program->gamification();
verify($config['reactivation_days']===180 && $config['reactivation_points']===30 && !$config['reactivation_enabled'],'Agreed defaults are available without silently enabling the bonus');
$config=$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_enabled'=>true,'reactivation_days'=>180,'reactivation_points'=>30]);
$s->execute('UPDATE companies SET reactivation_policy_at=? WHERE id=1',[date('Y-m-d H:i:s',time()-86400)]);
$reactivation=new DoctorReactivationService(new CareService($s,$doctor));
foreach([$nurse,$manager,$admin,$navigator,$worker,$dependent] as $actor) {
    denied(fn()=>(new DoctorReactivationService(new CareService($s,$actor)))->view(),403);
    denied(fn()=>(new DoctorReactivationService(new CareService($s,$actor)))->sync(),403);
}
$reactivationUser=$s->insert('users',['company_id'=>1,'name'=>'Retomada fictícia','email'=>'reactivation@test.invalid','password_hash'=>'unused','role'=>'worker']);
$reactivationPatient=$s->insert('patients',['company_id'=>1,'user_id'=>$reactivationUser,'name'=>'Pessoa com retomada fictícia']);
$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$reactivationPatient,'team_id'=>1]);
$oldVisit=$s->insert('appointments',['company_id'=>1,'patient_id'=>$reactivationPatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()-200*86400),'status'=>'attended']);
$baseline=$reactivation->sync()['points'];
verify((bool)array_filter($reactivation->view()['opportunities'],fn($p)=>$p['patient_id']===$reactivationPatient),'Known long interval is an opportunity, not an automatic award');
$returnVisit=$s->insert('appointments',['company_id'=>1,'patient_id'=>$reactivationPatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+86400),'status'=>'expected']);
verify($reactivation->sync()['points']===$baseline,'Booking alone never earns reactivation points');
$s->execute('UPDATE appointments SET status=?,scheduled_at=? WHERE id=?',['confirmed',date('Y-m-d H:i:s',time()-3600),$returnVisit]);
verify($reactivation->sync()['points']===$baseline,'Confirmation is not completed care');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['attended',$returnVisit]);
verify($reactivation->sync()['points']===$baseline+30,'Doctor of completed care receives the configured bonus');
verify($reactivation->sync()['points']===$baseline+30,'Repeated refreshes cannot multiply bonus');
$newPlan=(new CareService($s,$doctor))->create(['patient_id'=>$reactivationPatient,'professional_id'=>1,'team_id'=>1,'start_date'=>date('Y-m-d'),'reassessment_date'=>date('Y-m-d',time()+86400),'objectives'=>'Acompanhamento fictício','interventions'=>'Conduta pactuada fictícia','status'=>'active','clinical_notes'=>'Não deve aparecer na pontuação'])['id'];
(new CareService($s,$doctor))->evolution($newPlan,['kind'=>'clinical','notes'=>'Registro posterior à consulta fictícia.']);
verify($reactivation->sync()['points']===$baseline+30,'Consultation plus notes in the same return do not earn twice');
$award=$s->one('SELECT * FROM doctor_reactivation_awards WHERE patient_id=?',[$reactivationPatient]);
verify((int)$award['gap_days']>=180 && (int)$award['professional_id']===1,'Award stores gap, threshold and actual professional attribution');
$config=$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_enabled'=>true,'reactivation_days'=>90,'reactivation_points'=>50]);
verify($reactivation->sync()['points']===$baseline+30,'Changing future rules never reprices prior earned bonuses');
denied(fn()=>$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_days'=>0]),422);
denied(fn()=>$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_points'=>1001]),422);
$off=$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_enabled'=>false]);
verify($reactivation->sync()===['enabled'=>false],'Company may disable physician bonus independently');
verify((int)$s->one('SELECT COUNT(*) n FROM doctor_reactivation_awards WHERE patient_id=?',[$reactivationPatient])['n']===1,'Disabling preserves award history');
$config=$program->setGamification(['enabled'=>true,'version'=>$off['version'],'reactivation_enabled'=>true]);
verify($reactivation->sync()['points']===$baseline+30,'Re-enabling preserves the original recognition');
$unknownId=$s->insert('users',['company_id'=>1,'name'=>'Sem histórico','email'=>'unknown-reactivation@test.invalid','password_hash'=>'unused','role'=>'worker']);
$unknownPatient=$s->insert('patients',['company_id'=>1,'user_id'=>$unknownId,'name'=>'Sem histórico conhecido']);$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$unknownPatient,'team_id'=>1]);
$s->insert('appointments',['company_id'=>1,'patient_id'=>$unknownPatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s'),'status'=>'attended']);
verify($reactivation->sync()['points']===$baseline+30,'First known visit cannot prove a long absence');
$s->execute('UPDATE care_team_assignments SET active=0 WHERE patient_id=?',[$reactivationPatient]);
verify(!array_filter($reactivation->view()['items'],fn($p)=>$p['patient_id']===$reactivationPatient),'Revoked patients disappear from physician recognition details');
$s->execute('UPDATE care_team_assignments SET active=1 WHERE patient_id=?',[$reactivationPatient]);
verify($s->one('SELECT id FROM audit_logs WHERE event=?',['reactivation_awarded'])!==null,'Recognition is audited');
// New independent lapse scenarios use the approved rule.
$config=$program->setGamification(['enabled'=>true,'version'=>$config['version'],'reactivation_enabled'=>true,'reactivation_days'=>180,'reactivation_points'=>30]);
$s->execute('UPDATE companies SET reactivation_policy_at=? WHERE id=1',[date('Y-m-d H:i:s',time()-86400)]);
$makeReturn=function(string $tag,int $gap,?int $intervening=null,int $professional=1)use($s) {
    $user=$s->insert('users',['company_id'=>1,'name'=>$tag,'email'=>$tag.'@reactivation.test.invalid','password_hash'=>'unused','role'=>'worker']);
    $patient=$s->insert('patients',['company_id'=>1,'user_id'=>$user,'name'=>$tag]);
    $s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$patient,'team_id'=>1]);
    $returned=time()-60;
    $s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',$returned-$gap*86400),'status'=>'attended']);
    if($intervening) $s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>$intervening,'scheduled_at'=>date('Y-m-d H:i:s',$returned-10*86400),'status'=>'attended']);
    $visit=$s->insert('appointments',['company_id'=>1,'patient_id'=>$patient,'professional_id'=>$professional,'scheduled_at'=>date('Y-m-d H:i:s',$returned),'status'=>'attended']);
    return [$patient,$visit];
};
$current=$reactivation->sync()['points'];
[$shortPatient]=$makeReturn('short-gap',179);
verify($reactivation->sync()['points']===$current,'179 days does not meet 180-day threshold');
[$boundaryPatient,$boundaryVisit]=$makeReturn('exact-boundary',180);
verify($reactivation->sync()['points']===$current+30,'Exactly 180 full days qualifies');
$current+=30;
[$nursePatient]=$makeReturn('nursing-reset',200,(int)$nurse['id']);
verify($reactivation->sync()['points']===$current,'Intervening nursing care resets gap without awarding doctor');
[$wrongPatient]=$makeReturn('actual-author',200,null,(int)$nurse['id']);
verify($reactivation->sync()['points']===$current,'Assigned doctor cannot claim another professional attendance');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['cancelled',$boundaryVisit]);
verify($reactivation->sync()['points']===$current-30,'Corrected attendance removes unsupported recognition');
verify($s->one('SELECT status FROM doctor_reactivation_awards WHERE patient_id=?',[$boundaryPatient])['status']==='corrected','Correction preserves auditable ledger');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['attended',$boundaryVisit]);
verify($reactivation->sync()['points']===$current,'Restoring original evidence revalidates one original award');

echo "OK: {$count} combined reactivation/domain checks\n";
